solution.text:
_TOKENS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def to_roman(number):
    """Roman numeral for an int from 1 to 3999."""
    if not isinstance(number, int) or isinstance(number, bool) or not 1 <= number <= 3999:
        raise ValueError("expected an integer from 1 to 3999")

    parts = []
    for value, token in _TOKENS:
        count, number = divmod(number, value)
        parts.append(token * count)
    return "".join(parts)


def from_roman(text):
    """The int for a standard Roman numeral."""
    if not isinstance(text, str) or not text:
        raise ValueError("expected a Roman numeral")

    position = 0
    number = 0
    for value, token in _TOKENS:
        while text.startswith(token, position):
            number += value
            position += len(token)
    if position != len(text) or to_roman(number) != text:
        raise ValueError("expected a standard Roman numeral")
    return number
